//! Engine script API (functions + constants), generated by tools/gen_engine_api.py
//! from the LegacyClonk source (signatures) and lcdocs (descriptions, English via en.po).

use lazy_static::lazy_static;
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Debug, Deserialize)]
pub struct EngineParam {
    pub name: String,
    #[serde(rename = "type")]
    pub ty: String,
    /// the type the engine converts the argument to (C++ signature, e.g. C4Value = any); `ty` is the documented one
    #[serde(default)]
    pub etype: String,
    #[serde(default)]
    pub desc: String,
}

#[derive(Debug, Deserialize)]
pub struct EngineFunc {
    pub params: Option<Vec<EngineParam>>,
    #[serde(default)]
    pub rtype: String,
    /// return type from the C++ signature (any = C4Value)
    #[serde(default)]
    pub ertype: String,
    #[serde(default)]
    pub desc: String,
    #[serde(default)]
    pub remark: String,
    #[serde(default)]
    pub version: String,
    #[serde(default)]
    pub arity_known: bool,
}

#[derive(Debug, Deserialize)]
pub struct EngineConst {
    #[serde(rename = "type")]
    pub ty: String,
    pub value: String,
}

#[derive(Debug, Deserialize)]
pub struct EngineApi {
    pub functions: HashMap<String, EngineFunc>,
    pub constants: HashMap<String, EngineConst>,
}

const RAW: &str = include_str!("../core/engine_api.json");

lazy_static! {
    pub static ref ENGINE: EngineApi = serde_json::from_str(RAW).expect("engine_api.json is invalid");
}

/// Language keywords that the grammar may hand us as identifiers or calls.
pub const KEYWORDS: &[&str] = &[
    "this", "global", "Par", "inherited", "_inherited", "nil", "true", "false", "return", "break",
    "continue", "else", "if", "while", "for", "var", "local", "static", "new", "func", "goto", "in",
    "do", "eval",
];

impl EngineFunc {
    pub fn signature(&self, name: &str) -> String {
        let params = match &self.params {
            Some(ps) => ps.iter().map(|p| format!("{} {}", p.ty, p.name)).collect::<Vec<_>>().join(", "),
            None => "...".to_string(),
        };
        let rtype = if self.rtype.is_empty() { "any" } else { &self.rtype };
        format!("{} {}({})", rtype, name, params)
    }

    pub fn hover_markdown(&self, name: &str) -> String {
        let mut s = format!("```c4script\n{}\n```\n*engine function*", self.signature(name));
        if !self.version.is_empty() {
            s.push_str(&format!(" (since {})", self.version));
        }
        if !self.desc.is_empty() {
            s.push_str(&format!("\n\n{}", self.desc));
        }
        if let Some(ps) = &self.params {
            let documented: Vec<_> = ps.iter().filter(|p| !p.desc.is_empty()).collect();
            if !documented.is_empty() {
                s.push_str("\n");
                for p in documented {
                    s.push_str(&format!("\n- `{}`: {}", p.name, p.desc));
                }
            }
        }
        if !self.remark.is_empty() {
            s.push_str(&format!("\n\n{}", self.remark));
        }
        s
    }
}
